mapper.select:
SELECT R.REVIEWIDX, R.SALEREVIEWTYPE, R.CONTENT, R.REVIEWTAGS, TO_CHAR(R.CREATEDDATE, 'YYYY-MM-DD HH24:MI') AS createdDate, R.CREATEDDATE AS rawCreatedDate, R.SCORE, R.USERIDX, R.PRODUCTIDX, U.NICKNAME AS writerNickname, U.PROFILE_PHOTO AS profilePhoto, (SELECT REG.DONG FROM USERREGION UR JOIN REGION REG ON UR.REGIONCODE = REG.REGIONCODE WHERE UR.USERIDX = U.USERIDX AND UR.IS_ACTIVE = 1 FETCH FIRST 1 ROWS ONLY) AS writerAddr, P.TITLE AS productTitle FROM TRADINGREVIEWS R LEFT JOIN USERS U ON R.USERIDX = U.USERIDX LEFT JOIN PRODUCT P ON R.PRODUCTIDX = P.PRODUCTIDX
R.ISHIDDEN = 0
AND EXISTS ( SELECT 1 FROM TRADETRANSACTION T WHERE T.PRODUCTIDX = R.PRODUCTIDX AND ((T.SELLERIDX = #{userIdx} AND R.SALEREVIEWTYPE = 'BUYER') OR (T.BUYERIDX = #{userIdx} AND R.SALEREVIEWTYPE = 'SELLER')) )
AND R.USERIDX = #{userIdx}
AND R.USERIDX = #{userIdx}
ORDER BY R.REVIEWIDX DESC

mapper.insert:
INSERT INTO TRADINGREVIEWS (
    REVIEWIDX, SALEREVIEWTYPE, CONTENT, USERIDX, PRODUCTIDX, SCORE, REVIEWTAGS
) VALUES (
    SEQTRADINGREVIEWS.NEXTVAL, #{saleReviewType}, #{content}, #{userIdx}, #{productIdx}, #{score}, #{reviewTags}
)
